-- Section 110 — Industrialisation Band 5 Sprint
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var industrialiseringen samlet set en fordel eller en ulempe for den brede befolkning i 1800-tallets England — og hvad afgør svaret?","options":["Svaret afhænger af tidsperspektiv og hvem man måler på: de første generationer af fabriksarbejdere og slumboere bar den fulde sociale og sundhedsmæssige byrde mens gevinsten primært tilfaldt kapitalejerne. Den langtsigtede levestandardsstigning var reel men ekstremt skævt fordelt og ankom årtier for sent for dem der led under overgangen","Industrialiseringen var entydigt positiv for alle sociale lag — teknologisk fremgang og vækst forbedrede automatisk alle borgeres levevilkår over den samme periode","Industrialiseringen var udelukkende skadelig og producerede ingen reelle fordele for nogen del af befolkningen — al fremgang er en ideologisk konstruktion","Det er historisk metodisk umuligt at vurdere om industrialiseringen var positiv eller negativ og spørgsmålet bør ikke stilles"],"correct":"Svaret afhænger af tidsperspektiv og hvem man måler på: de første generationer af fabriksarbejdere og slumboere bar den fulde sociale og sundhedsmæssige byrde mens gevinsten primært tilfaldt kapitalejerne. Den langtsigtede levestandardsstigning var reel men ekstremt skævt fordelt og ankom årtier for sent for dem der led under overgangen","accepted_answers":["Svaret afhænger af tidsperspektiv og hvem man måler på: de første generationer af fabriksarbejdere og slumboere bar den fulde sociale og sundhedsmæssige byrde mens gevinsten primært tilfaldt kapitalejerne. Den langtsigtede levestandardsstigning var reel men ekstremt skævt fordelt og ankom årtier for sent for dem der led under overgangen"],"review_text":"Levestandards-debatten er industrialiseringshistoriografiens centrale metodologiske stridspunkt. Optimister som Robert Allen og Joel Mokyr dokumenterer at reallønningerne over 1760-1860 steg i gennemsnit. Pessimister som E.P. Thompson og John og Barbara Hammond viser at aggregerede gennemsnit skjuler ekstrem ulighed: tekstilhåndværkere mistede indkomst mens fabriksejere akkumulerede kapital. Forventet levealder i Manchester i 1840 var 28 år — lavere end landsgennemsnittet. Friedrich Engels dokumenterede i The Condition of the Working Class in England (1845) med primær empirisk grundighed at Manchesters vækst og Manchesters elendighed var to sider af samme mønt. Spørgsmålet om 'samlet fordel' kræver en etisk fordelingsbeslutning: hvem tæller, over hvilken periode og med hvilken målestok."}$$::jsonb,
  'mc','short',$${"concepts":["levestandard","industrialisering","fordeling","Engels","optimisme vs pessimisme","tidsperspektiv"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad afslørede urbaniseringen under industrialiseringen om forholdet mellem økonomisk vækst og social velfærd?","options":["At vækst og velfærd ikke automatisk følges ad: Manchester, Birmingham og London voksede eksplosivt i befolkning og produktion men producerede simultant slumkvarterer, forurenet drikkevand, koleraepidermier og katastrofale leveforhold. Kapitalakkumulation og menneskelig velfærd var adskillelige størrelser der kræver aktiv politisk forbindelsesled","At urbanisering automatisk forbedrer velfærd fordi bykoncentration muliggør bedre adgang til arbejde, handel og tjenester for alle","At forholdet er tilfældigt og hvert enkelt tilfælde af urbanisering er unikt og ikke kan generaliseres","At det er falsk at tale om social velfærd som et selvstændigt mål — den eneste relevante målestok er samlet BNP-vækst"],"correct":"At vækst og velfærd ikke automatisk følges ad: Manchester, Birmingham og London voksede eksplosivt i befolkning og produktion men producerede simultant slumkvarterer, forurenet drikkevand, koleraepidermier og katastrofale leveforhold. Kapitalakkumulation og menneskelig velfærd var adskillelige størrelser der kræver aktiv politisk forbindelsesled","accepted_answers":["At vækst og velfærd ikke automatisk følges ad: Manchester, Birmingham og London voksede eksplosivt i befolkning og produktion men producerede simultant slumkvarterer, forurenet drikkevand, koleraepidermier og katastrofale leveforhold. Kapitalakkumulation og menneskelig velfærd var adskillelige størrelser der kræver aktiv politisk forbindelsesled"],"review_text":"Manchesters befolkning voksede fra 25.000 i 1772 til 300.000 i 1850. Infrastrukturen og boligmassen fulgte ikke med: Engels dokumenterede i 1845 at arbejderne boede i fugtfyldte kældre, delte toiletter med 200 naboer og drak vand fra åer der modtog fabriksaffald og kloakspildevand. John Snow kortlagde i 1854 at koleraepidemien i Soho var vandbåren — og demonstrerede at urbaniseringens velfærdsproblemer var løsbare med politisk vilje og infrastrukturinvestering. Den moderne parallellen er tydelig: Kinas og Indiens urbanisering 1990-2020 producerede lignende spændinger mellem væksttal og menneskelige levevilkår. Vækst er ikke det samme som velfærd — men velfærd kræver en produktiv økonomi der kan finansiere infrastruktur og sociale systemer. Forbindelsen er politisk konstrueret, ikke automatisk."}$$::jsonb,
  'mc','short',$${"concepts":["urbanisering","vækst vs velfærd","Manchester","Engels","kolera","kapitalakkumulation"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser børnearbejdet under industrialiseringen om forholdet mellem 'historisk nødvendighed' og etisk ansvar?","options":["At nødvendighed ikke er en tilstrækkelig etisk begrundelse: børnearbejde blev rationaliseret som uundgåeligt og endda gavnligt (disciplin, familiebidrag) men reformernes succes viser at alternativer eksisterede — og de rige ejere der tjente på det accepterede ikke selv samme nødvendighed for egne børn. Dobbeltstandarden afslører at argumentet var en magtrationalisation snarere end en etisk analyse","Børnearbejde var historisk nødvendigt og uundgåeligt — det var den eneste måde familier i fattigdom kunne overleve og ændringen kom naturligt da samfundet blev rigere","Børnearbejde var fuldstændig frivilligt og accepteret af alle involverede parter og etisk kritik er en anakronistisk projektion af nutidige værdier på fortiden","Etisk vurdering af historiske praksisser er metodisk illegitimt — historikere bør kun beskrive hvad der skete og ikke evaluere det"],"correct":"At nødvendighed ikke er en tilstrækkelig etisk begrundelse: børnearbejde blev rationaliseret som uundgåeligt og endda gavnligt (disciplin, familiebidrag) men reformernes succes viser at alternativer eksisterede — og de rige ejere der tjente på det accepterede ikke selv samme nødvendighed for egne børn. Dobbeltstandarden afslører at argumentet var en magtrationalisation snarere end en etisk analyse","accepted_answers":["At nødvendighed ikke er en tilstrækkelig etisk begrundelse: børnearbejde blev rationaliseret som uundgåeligt og endda gavnligt (disciplin, familiebidrag) men reformernes succes viser at alternativer eksisterede — og de rige ejere der tjente på det accepterede ikke selv samme nødvendighed for egne børn. Dobbeltstandarden afslører at argumentet var en magtrationalisation snarere end en etisk analyse"],"review_text":"Børnearbejde i engelske bomuldsfabrikker, miner og skorstensfejeriet var udbredt og veldokumenteret. Fabrikskommissionen af 1832 indsamlede vidneudsagn fra børn der arbejdede 12-14 timer dagligt fra seksårsalderen. Argumentet om nødvendighed var udbredt: fattige familier havde brug for børnenes indkomst. Men dobbeltstandarden var åbenlys: de fabriksejere og parlamentsmedlemmer der forsvarede børnearbejde sendte egne børn til private skoler. Fabriksloven af 1833 forbød børnearbejde under ni år — og industrien overlevede. Historisk-etisk analyse kræver ikke anakronisme: reformatorerne selv (Lord Shaftesbury, Robert Owen) opererede med etiske kategorier der var samtidige, ikke eftertidens påfund. Nødvendighed-argumentet er en strukturelt genkommende rationalisering for magtasymmetriske relationer der genfindes i debatter om sweatshops og uformelt økonomiarbejde i dag."}$$::jsonb,
  'mc','short',$${"concepts":["børnearbejde","historisk nødvendighed","etisk dobbeltstandard","Shaftesbury","fabrikslov","magtrationalisation"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den langtrækkende konsekvens af arbejdsdelingen under industrialiseringen — og hvordan adskiller Adam Smiths og Karl Marx' analyser sig?","options":["Smith og Marx observerer det samme fænomen men vurderer det modsatrettet: Smith (Wealth of Nations 1776) priser arbejdsdeling som effektivitetens motor — naalsefabrikken der producerer 4800 gange mere med specialiseret arbejdskraft. Marx videreudvikler analysen kritisk: specialisering alienerer arbejderen fra produktet, fra processen og fra sin menneskelige kreativitet — effektivitet købt med menneskelig fragmentering","Smith og Marx er enige om at arbejdsdeling er udelukkende positiv og begge fremhæver den som industrialiseringens afgørende succesfaktor","Marx afviser arbejdsdelingen fuldstændigt og mener specialisering aldrig bidrager til produktivitet — kun til undertrykkelse","Arbejdsdeling er et rent teknisk fænomen uden sociale eller etiske dimensioner som Marx og Smith begge ignorerer"],"correct":"Smith og Marx observerer det samme fænomen men vurderer det modsatrettet: Smith (Wealth of Nations 1776) priser arbejdsdeling som effektivitetens motor — naalsefabrikken der producerer 4800 gange mere med specialiseret arbejdskraft. Marx videreudvikler analysen kritisk: specialisering alienerer arbejderen fra produktet, fra processen og fra sin menneskelige kreativitet — effektivitet købt med menneskelig fragmentering","accepted_answers":["Smith og Marx observerer det samme fænomen men vurderer det modsatrettet: Smith (Wealth of Nations 1776) priser arbejdsdeling som effektivitetens motor — naalsefabrikken der producerer 4800 gange mere med specialiseret arbejdskraft. Marx videreudvikler analysen kritisk: specialisering alienerer arbejderen fra produktet, fra processen og fra sin menneskelige kreativitet — effektivitet købt med menneskelig fragmentering"],"review_text":"Adam Smiths berømte naalsefabrik-eksempel i Wealth of Nations åbningskapitel illustrerer arbejdsdelingens effektivitetspotentiale: ti specialiserede arbejdere producerer 48.000 naale dagligt mod én ufaglærts 20. Smiths analyse er overvejende positiv og ser lønstigning og velstandsvækst som de naturlige resultater. Marx Ökonomisch-philosophische Manuskripte (1844) vender analysen: det er præcis den fuldstændige specialisering der reducerer arbejderen til et appendiks til maskinen. Alienationsbegrebet — fra produkt, fra produktionsproces, fra menneskets artsvæsen og fra andre mennesker — er Marx' centrale svar på industrialismens menneskelige dimension. Debatten er fortsat relevant: monotont fabriksarbejde vs kreativt videnarbejde og gig-økonomiens platform-arbejde rejser identiske spørgsmål om kontrol og mening i arbejdet."}$$::jsonb,
  'mc','short',$${"concepts":["arbejdsdeling","Smith","Marx","alienation","effektivitet","Wealth of Nations"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kernen i marxistisk analyse af industrialiseringen — og hvad er de stærkeste metodologiske indvendinger mod den?","options":["Marx: industrialiseringen er kapitalismens fundamentale modsætning i praksis — bourgeoisiet akkumulerer kapital ved at appropriere merværdien af proletariatets ubetalte arbejdstid. Indvendinger: den historiske determinisme undervurderer aktørers handlefrihed og kulturelle faktorer, og forudsigelsen om kapitalistisk kollaps via intensiverende klassekamp er ikke indtrådt som forudsagt","Marx er fuldstændig korrekt og alle indvendinger er politisk motiverede forsvar for kapitalistiske interesser uden metodologisk substans","Marx-analysen er fuldstændig forkert fordi kapitalisme historisk ikke har produceret udbytning men derimod stigning i levestandard for alle klasser","Marxistisk analyse er kun relevant for 1800-tallets England og kan ikke anvendes analytisk på industrialiseringsprocesser i andre lande eller perioder"],"correct":"Marx: industrialiseringen er kapitalismens fundamentale modsætning i praksis — bourgeoisiet akkumulerer kapital ved at appropriere merværdien af proletariatets ubetalte arbejdstid. Indvendinger: den historiske determinisme undervurderer aktørers handlefrihed og kulturelle faktorer, og forudsigelsen om kapitalistisk kollaps via intensiverende klassekamp er ikke indtrådt som forudsagt","accepted_answers":["Marx: industrialiseringen er kapitalismens fundamentale modsætning i praksis — bourgeoisiet akkumulerer kapital ved at appropriere merværdien af proletariatets ubetalte arbejdstid. Indvendinger: den historiske determinisme undervurderer aktørers handlefrihed og kulturelle faktorer, og forudsigelsen om kapitalistisk kollaps via intensiverende klassekamp er ikke indtrådt som forudsagt"],"review_text":"Marx's Das Kapital (1867) er den mest systematiske analyse af industrialismens politiske økonomi. Merværditeorien: arbejderen sælger sin arbejdskraft til en løn svarende til reproduktionsomkostningerne, men arbejder et overskud ud over denne løn som kapitalisten approprierer som profit. Udbytning er i Marx's analyse ikke moralsk anklagende men strukturel. Metodologiske indvendinger er tungtvejende: Karl Poppers kritik af historisk determinisme viser at Marx's forudsigelser om kapitalistisk sammenbrud er ikke-falsificerbare. Max Webers The Protestant Ethic viser at kulturelle faktorer spillede en selvstændig rolle Marx undervurderede. Ikke desto mindre er merværdi-analysen og kapitalakkumulationsteorien fortsat metodologisk frugtbare redskaber til at analysere indkomstulighed og finanskapitalisme i det 21. århundrede."}$$::jsonb,
  'mc','short',$${"concepts":["Marx","merværdi","kapitalakkumulation","historisk determinisme","Das Kapital","Weber"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den afgørende antagelse der skiller liberalistisk og socialistisk fortolkning af industrialiseringens sociale problemer?","options":["Liberalister ser problemerne som markedssvigt der kan rettes med reformer mens grundstrukturen bevares — socialister ser dem som strukturelt uadskillelige fra kapitalistisk ejendomsret til produktionsmidlerne. Den afgørende antagelse: om privat ejerskab af fabrikker og kapital er problemets løsning, en neutral faktor eller problemets årsag","Liberalister og socialister er enige om problemernes årsag men uenige om løsningerne — den ideologiske forskel er rent proceduralt","Socialister mener at alle sociale problemer løses automatisk ved statslig overtagelse af produktionsmidlerne og liberalister mener at alle problemer løses automatisk ved frimarkeder","Ideologisk fortolkning er uvidenskabelig og historikere bør undgå at anvende hverken liberalistiske eller socialistiske analytiske rammer"],"correct":"Liberalister ser problemerne som markedssvigt der kan rettes med reformer mens grundstrukturen bevares — socialister ser dem som strukturelt uadskillelige fra kapitalistisk ejendomsret til produktionsmidlerne. Den afgørende antagelse: om privat ejerskab af fabrikker og kapital er problemets løsning, en neutral faktor eller problemets årsag","accepted_answers":["Liberalister ser problemerne som markedssvigt der kan rettes med reformer mens grundstrukturen bevares — socialister ser dem som strukturelt uadskillelige fra kapitalistisk ejendomsret til produktionsmidlerne. Den afgørende antagelse: om privat ejerskab af fabrikker og kapital er problemets løsning, en neutral faktor eller problemets årsag"],"review_text":"Den liberalistiske reaktion på industrialiseringens sociale problemer (John Stuart Mill, New Liberalism) var reform: fabrikslove, sundhedslov, arbejdsforsikring — alt mens det kapitalistiske system bevaredes. Den socialistiske analyse (Marx, Robert Owen, Fabian Society) hævdede at dette var utilstrækkeligt: så længe produktionsmidlerne var privat ejet, ville kapitalens logik systematisk reproducere udbytning. Robert Owen demonstrerede at fabriksdrift under sociale principper var mulig (New Lanark) — men Owens succes afhang af hans personlige godhed, ikke af systemets struktur. Den afgørende antagelse om ejendomsrettens rolle afgør om reformisme eller systemskifte er den logiske konklusion. Denne grundlæggende uenighed strukturerer fortsat politisk debat om velfærdsstat, markedsregulering og klimapolitik."}$$::jsonb,
  'mc','short',$${"concepts":["liberalisme","socialisme","ejendomsret","markedssvigt","reformisme","Owen"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er kapitalisme og demokrati historisk nødvendigvis forbundne — og hvad viser empirien om dette forhold?","options":["Ikke nødvendigvis: kapitalisme har eksisteret under autoritære regimer (Pinochet-Chiles markedskapitalisme, Kinas statskapitalisme) og demokrati har eksisteret med stærk statsintervention (skandinavisk velfærdskapitalisme). Relationen er kontingent og historisk formet — ikke strukturelt nødvendig","Kapitalisme og demokrati er historisk identiske og har altid fulgt hinanden — demokrati kan ikke eksistere uden privat ejendomsret til produktionsmidlerne","Demokrati er uforenelig med kapitalisme fordi kapitalens magt systematisk korrumperer demokratiske institutioner — historien beviser dette entydigt","Spørgsmålet om kapitalisme og demokrati er rent ideologisk og kan ikke undersøges empirisk"],"correct":"Ikke nødvendigvis: kapitalisme har eksisteret under autoritære regimer (Pinochet-Chiles markedskapitalisme, Kinas statskapitalisme) og demokrati har eksisteret med stærk statsintervention (skandinavisk velfærdskapitalisme). Relationen er kontingent og historisk formet — ikke strukturelt nødvendig","accepted_answers":["Ikke nødvendigvis: kapitalisme har eksisteret under autoritære regimer (Pinochet-Chiles markedskapitalisme, Kinas statskapitalisme) og demokrati har eksisteret med stærk statsintervention (skandinavisk velfærdskapitalisme). Relationen er kontingent og historisk formet — ikke strukturelt nødvendig"],"review_text":"Den ideologiske påstand om kapitalisme-demokrati-nødvendighed er empirisk uholdbar. Pinochet-Chiles kapitalisme (1973-1990) var designet af Chicago School-økonomer og implementeret under militærdiktatur. Singapore kombinerer markedskapitalisme med en-parti-styre. Kinas kapitalistiske vækst sker under Kommunistpartiets monopol. Skandinaviske lande kombinerer demokratisk tradition med stærk statsintervention. Barrington Moores Social Origins of Dictatorship and Democracy (1966) viste at landboklassens rolle var afgørende for demokratiets fremkomst — ikke kapitalismens per se. Den analytisk korrekte position: kapitalisme og demokrati er kompatible men hverken gensidigt forudsætter eller udelukker hinanden. Forbindelsen er historisk og politisk konstrueret."}$$::jsonb,
  'mc','short',$${"concepts":["kapitalisme","demokrati","Pinochet","Kina","skandinavisk model","Moore"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var Robert Owens eksperiment i New Lanark — og hvad viser dets succes og grænser om industrialismens muligheder?","options":["New Lanark viste at industriel produktion under sociale principper var både mulig og rentabel: Owen indførte 10-timers arbejdsdag, forbød børnearbejde under ti år, byggede skole og forbrugskooperativ og forøgede samtidig fabrikkens profit. Eksperimentets grænse: successen afhang af Owens personlige ledelse og kapital — det demonstrerede ikke at markedet automatisk producerer sådanne resultater uden ekstern tvang","New Lanark viste at sociale reformer altid svækker produktiviteten og er uforenelige med rentabel industriproduktion","New Lanark er et isoleret tilfælde uden analytisk relevans for industrialiseringens overordnede mønstre og bør ikke bruges i generelle argumenter","Owen demonstrerede at statslig overtagelse af alle fabrikker er den eneste vej til social industri — privat ejede fabrikker kan aldrig reformeres"],"correct":"New Lanark viste at industriel produktion under sociale principper var både mulig og rentabel: Owen indførte 10-timers arbejdsdag, forbød børnearbejde under ti år, byggede skole og forbrugskooperativ og forøgede samtidig fabrikkens profit. Eksperimentets grænse: successen afhang af Owens personlige ledelse og kapital — det demonstrerede ikke at markedet automatisk producerer sådanne resultater uden ekstern tvang","accepted_answers":["New Lanark viste at industriel produktion under sociale principper var både mulig og rentabel: Owen indførte 10-timers arbejdsdag, forbød børnearbejde under ti år, byggede skole og forbrugskooperativ og forøgede samtidig fabrikkens profit. Eksperimentets grænse: successen afhang af Owens personlige ledelse og kapital — det demonstrerede ikke at markedet automatisk producerer sådanne resultater uden ekstern tvang"],"review_text":"Robert Owens bomuldsfabrik i New Lanark i Skotland var det mest kendte industrielle socialeksperiment i 1800-tallet. Owen overtog fabrikken i 1799 og indførte revolutionerende betingelser: ingen børnearbejde under ti år (årtier før loven krævede det), daglig skolegang for alle arbejderbørn og en forbrugskooperativ der solgte til kostpris. Fabrikkens profit forblev høj og New Lanark blev et pilgrimssted for sociale reformatorer fra hele Europa. Grænsen var institutionel: Owen var selv den paternalistiske velgører der holdt systemet oppe. Hans New Harmony-koloni i USA (1825) kollapsede. Paradokset i Owens projekt er klassisk: det demonstrerede at sociale reformer og profit er forenelige men beviste ikke at markedets konkurrencelogik producerer dette resultat automatisk. Corporate Social Responsibility og B-corp-bevægelsen møder den samme institutionelle grænse i dag."}$$::jsonb,
  'mc','short',$${"concepts":["Robert Owen","New Lanark","reformkapitalisme","kooperativ","paternalisme","institutionel grænse"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var fagforeningernes fremvækst under industrialiseringen et legitimt demokratisk svar på magtasymmetrien — og hvad er det stærkeste argument imod dem?","options":["Legitim magtbalancering: individuelle arbejdere stod uden forhandlingsstyrke overfor kapitalejere der kunne erstatte enhver enkelt arbejder — kollektiv organisering kompenserede for den strukturelle magtasymmetri og producerede lønforbedringer og bedre vilkår. Stærkeste modargument: fagforeninger kan blive monopolistiske og beskytte allerede ansatte insiders på bekostning af ledige og nyindtrædende outsiders","Fagforeninger var udelukkende destruktive og undergravede industrialiseringens produktivitetsvækst uden at producere nogen reel fordel for arbejderne","Fagforeninger er altid legitime og der er ingen holdbare argumenter imod dem — alle indvendinger er kapitalinteressers politiske rationalisering","Fagforeninger var unødvendige fordi markedet automatisk sikrer retfærdige lønninger via konkurrencen om arbejdskraft"],"correct":"Legitim magtbalancering: individuelle arbejdere stod uden forhandlingsstyrke overfor kapitalejere der kunne erstatte enhver enkelt arbejder — kollektiv organisering kompenserede for den strukturelle magtasymmetri og producerede lønforbedringer og bedre vilkår. Stærkeste modargument: fagforeninger kan blive monopolistiske og beskytte allerede ansatte insiders på bekostning af ledige og nyindtrædende outsiders","accepted_answers":["Legitim magtbalancering: individuelle arbejdere stod uden forhandlingsstyrke overfor kapitalejere der kunne erstatte enhver enkelt arbejder — kollektiv organisering kompenserede for den strukturelle magtasymmetri og producerede lønforbedringer og bedre vilkår. Stærkeste modargument: fagforeninger kan blive monopolistiske og beskytte allerede ansatte insiders på bekostning af ledige og nyindtrædende outsiders"],"review_text":"Kombinationsloven af 1799-1800 forbød fagforeninger i England og kriminaliserede kollektiv lønforhandling. Ophævelsen i 1824-25 åbnede for fagforeningsdannelse. Den strukturelle analyse er klar: en individuel tekstilspinder stod uden forhandlingskraft overfor en fabriksejer der kunne ansætte et dusin alternative arbejdere. Kollektiv organisering var det rationelle svar på strukturel magtasymmetri. Det liberalekonomiske modargument (Hayek, Friedman) er metodologisk seriøst: fagforeninger med monopol på arbejdskraft kan sætte lønniveauer over markedsligevægt og derved reducere beskæftigelsen. Empirisk er effekten kontekstafhængig: stærke fagforeninger kombineret med koordineret lønforhandling (den skandinaviske model) producerer lave uligheder og høj beskæftigelse. Insider-outsider-problemet er reelt men ikke uundgåeligt."}$$::jsonb,
  'mc','short',$${"concepts":["fagforeninger","magtasymmetri","kollektiv forhandling","insider-outsider","Chartisme","kombinationsloven"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser reformlovenes gradvise indførelse i England (Factory Acts, Mines Act) om forholdet mellem social bevægelse og politisk forandring?","options":["At politisk forandring typisk kræver koalitioner af aktører: reformistiske parlamentarikere (Lord Shaftesbury), offentlig opinion mobiliseret af parlamentariske undersøgelseskommissioner og journalistisk dokumentation samt fagbevægelsens politiske pres. Ingen enkelt faktor var tilstrækkelig — og forandringen var gradvis og ufuldstændig, ikke brat og fuldstændig","At reformerne kom udelukkende fra godhjertede individuelle parlamentarikere og beviser at systemet kan reformere sig selv indefra uden social bevægelses pres","At reformerne alene skyldtes arbejdernes strejker og revolutionære trusler — parlamentarisk velvilje spillede ingen selvstændig rolle","At reformlovene var fuldt tilstrækkelige og løste alle industrialiseringens sociale problemer da de blev vedtaget"],"correct":"At politisk forandring typisk kræver koalitioner af aktører: reformistiske parlamentarikere (Lord Shaftesbury), offentlig opinion mobiliseret af parlamentariske undersøgelseskommissioner og journalistisk dokumentation samt fagbevægelsens politiske pres. Ingen enkelt faktor var tilstrækkelig — og forandringen var gradvis og ufuldstændig, ikke brat og fuldstændig","accepted_answers":["At politisk forandring typisk kræver koalitioner af aktører: reformistiske parlamentarikere (Lord Shaftesbury), offentlig opinion mobiliseret af parlamentariske undersøgelseskommissioner og journalistisk dokumentation samt fagbevægelsens politiske pres. Ingen enkelt faktor var tilstrækkelig — og forandringen var gradvis og ufuldstændig, ikke brat og fuldstændig"],"review_text":"Fabriksloven af 1833 begrænsede børnearbejde og indførte fabriksinspektører. Den kom ikke ud af ingenting: parlamentariske undersøgelseskommissioner (1832-33) indsamlede vidneudsagn, Lord Shaftesbury byggede parlamentarisk koalition og den voksende offentlige opmærksomhed via pamfletter og avisreportager mobiliserede middelklassens samvittighed. Mineloven af 1842 forbød kvinder og børn under ti i underjordisk minearbejde — efter at Ashley-kommissionens rapport med illustrationer af kvinder og børn på alle fire i minegangene chokerede parlamentet. Forandringsprocessen illustrerer en central indsigt: social forandring kræver typisk samspil mellem dokumentation (eksponering), moralisering (etisk fordømmelse), organisering (fagbevægelse, parlamentarisk lobby) og politisk mulighed (valgreform 1832 ændrede parlamentets sammensætning). Ingen enkelt faktor er tilstrækkelig alene."}$$::jsonb,
  'mc','short',$${"concepts":["fabriksloven","Shaftesbury","social reform","koalition","parlamentarisk undersøgelse","forandringsproces"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var afskaffelsen af børnearbejdet i England primært et resultat af moralsk fremskridt — eller af strukturelle ændringer der gjorde det kommercielt unødvendigt?","options":["Begge faktorer spillede selvstændige roller der er svære at adskille kausalt: fabrikslovene udtrykte reel moralsk reform drevet af reformatorer og offentlig opinion, men teknologisk udvikling reducerede parallelt behovet for børns specifikke motoriske bidrag i visse sektorer. At attribuere afskaffelsen til én faktor alene er en metodologisk forenkling","Afskaffelsen skyldtes udelukkende moralsk fremskridt og etisk erkendelse — strukturelle faktorer spillede ingen rolle","Børnearbejde ophørte automatisk da samfundet blev rigere og ingen reform var nødvendig — markedet løste problemet af sig selv","Afskaffelsen skyldtes udelukkende teknologiske ændringer der gjorde børnearbejde kommercielt urentabelt — moral og reform var ubetydelige faktorer"],"correct":"Begge faktorer spillede selvstændige roller der er svære at adskille kausalt: fabrikslovene udtrykte reel moralsk reform drevet af reformatorer og offentlig opinion, men teknologisk udvikling reducerede parallelt behovet for børns specifikke motoriske bidrag i visse sektorer. At attribuere afskaffelsen til én faktor alene er en metodologisk forenkling","accepted_answers":["Begge faktorer spillede selvstændige roller der er svære at adskille kausalt: fabrikslovene udtrykte reel moralsk reform drevet af reformatorer og offentlig opinion, men teknologisk udvikling reducerede parallelt behovet for børns specifikke motoriske bidrag i visse sektorer. At attribuere afskaffelsen til én faktor alene er en metodologisk forenkling"],"review_text":"Fabriksloven af 1833 og 1844 og Mineloven af 1842 afspejler reel parlamentarisk moralsk argumentation — reformatorerne brugte etiske kategorier om barndommens ukrænkelighed og statens beskyttelsespligt. Denne moralske dimension er ikke reducerbar til strukturelle faktorer. Samtidig er det empirisk korrekt at automatiseringen af visse processer (spinning jenny, power loom) reducerede det specifikke behov for børns smidighed og små hænder. Hugh Cunningham (The Children of the Poor, 1991) viser at afskaffelsen er et multi-kausal fænomen: reformistisk kampagne, industriel teknologi, stigende reallønninger der reducerede fattigfamiliernes afhæn­gighed af børneindkomst og voksende statskapacitet til håndhævelse. Den metodologiske pointe er generel: historiske forandringer er sjældent mono-kausale og at insistere på multi-kausalitet er ikke at undvige spørgsmålet — det er det rigtige svar."}$$::jsonb,
  'mc','short',$${"concepts":["børnearbejde","afskaffelse","moralsk reform","teknologisk udvikling","multi-kausalitet","Cunningham"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det stærkeste argument for statslig regulering af arbejdsmarkedet under industrialiseringen — og hvad er det liberalistiske modargument?","options":["For regulering: arbejdsmarkedet under industrialiseringen var strukturelt asymmetrisk — arbejdsgivere med monopsonimagt (eneste store arbejdsgiver i en region) kunne sætte lønninger under konkurrenceligevægt og diktere vilkår. Regulering korrigerede et markedssvigt, ikke et velfungerende marked. Modargument: regulering øger transaktionsomkostninger og reducerer fleksibilitet og kan i grænsetilfælde skade de fattigste ved at reducere beskæftigelsen","Regulering er altid unødvendig fordi markedet automatisk producerer optimale lønninger og arbejdsvilkår via prismekanismen","Statslig regulering er altid skadelig og enhver intervention forringer arbejdernes stilling — frimarked er altid det bedste svar","Regulering var kun nødvendig i England og er irrelevant for industrialiseringsprocesser i andre historiske kontekster"],"correct":"For regulering: arbejdsmarkedet under industrialiseringen var strukturelt asymmetrisk — arbejdsgivere med monopsonimagt (eneste store arbejdsgiver i en region) kunne sætte lønninger under konkurrenceligevægt og diktere vilkår. Regulering korrigerede et markedssvigt, ikke et velfungerende marked. Modargument: regulering øger transaktionsomkostninger og reducerer fleksibilitet og kan i grænsetilfælde skade de fattigste ved at reducere beskæftigelsen","accepted_answers":["For regulering: arbejdsmarkedet under industrialiseringen var strukturelt asymmetrisk — arbejdsgivere med monopsonimagt (eneste store arbejdsgiver i en region) kunne sætte lønninger under konkurrenceligevægt og diktere vilkår. Regulering korrigerede et markedssvigt, ikke et velfungerende marked. Modargument: regulering øger transaktionsomkostninger og reducerer fleksibilitet og kan i grænsetilfælde skade de fattigste ved at reducere beskæftigelsen"],"review_text":"Monopsoni-begrebet er afgørende for at forstå industritidens arbejdsmarked: i minebyerne i Wales eller tekstilbyerne i Lancashire var der typisk én dominerende arbejdsgiver. En individuel arbejder der nægtede fabriksejerens vilkår, stod uden realistiske alternativer. John Stuart Mills reaktion i Principles of Political Economy (1848) var at acceptere statslig regulering som et legitimt svar på markedssvigt. Det liberale modargument (Nassau Senior, Herbert Spencer) var at fabrikslove ville reducere britisk konkurrenceevne og skade de arbejdere de hævdede at beskytte. Empirisk viste dette sig forkert: fabrikslovenes implementering producerede ikke den forudsagte beskæftigelsesnedgang. Det metodologisk vigtige: argument om regulerings skadelighed er ikke forkert per definition men kræver empirisk belæg i den konkrete kontekst."}$$::jsonb,
  'mc','short',$${"concepts":["monopsoni","arbejdsmarkedsregulering","markedssvigt","Mill","fabrikslov","liberalisme"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den centrale strid i industrialiseringshistoriografien mellem 'optimister' og 'pessimister' — og hvad er den metodologiske kerne i uenigheden?","options":["Optimister (McCloskey, Clark) dokumenterer at reallønningerne steg over perioden 1760-1860 og argumenterer for netto-forbedring i levestandard. Pessimister (Thompson, Hammond) viser at aggregerede løntal skjuler ekstremt ulig fordeling og at levekvalitet (arbejdsforhold, sundhed, frihed, fællesskab) forringedes dramatisk. Metodekerne: hvad måler vi, for hvem og med hvilken enhed — løn, kaloriindtag, forventet levealder eller subjektiv erfaring","Optimisterne er entydigt korrekte og pessimisterne er marxistisk motiverede og empirisk forkerte","Pessimisterne er entydigt korrekte og optimisterne er apologeter for kapitalistiske interesser","Uenigheden er rent politisk og ikke en reel empirisk diskussion — begge sider er ideologisk motiverede"],"correct":"Optimister (McCloskey, Clark) dokumenterer at reallønningerne steg over perioden 1760-1860 og argumenterer for netto-forbedring i levestandard. Pessimister (Thompson, Hammond) viser at aggregerede løntal skjuler ekstremt ulig fordeling og at levekvalitet (arbejdsforhold, sundhed, frihed, fællesskab) forringedes dramatisk. Metodekerne: hvad måler vi, for hvem og med hvilken enhed — løn, kaloriindtag, forventet levealder eller subjektiv erfaring","accepted_answers":["Optimister (McCloskey, Clark) dokumenterer at reallønningerne steg over perioden 1760-1860 og argumenterer for netto-forbedring i levestandard. Pessimister (Thompson, Hammond) viser at aggregerede løntal skjuler ekstremt ulig fordeling og at levekvalitet (arbejdsforhold, sundhed, frihed, fællesskab) forringedes dramatisk. Metodekerne: hvad måler vi, for hvem og med hvilken enhed — løn, kaloriindtag, forventet levealder eller subjektiv erfaring"],"review_text":"Standard of living-debatten er industrialiseringshistoriografiens centrale metodologiske stridsfelt. Robert Allen og Gregory Clark har vist at reallønningerne steg i gennemsnit i perioden. Men E.P. Thompsons The Making of the English Working Class (1963) viste at denne statistiske fremgang skjuler dramatiske tab: håndvævernes løn kollapsede, arbejdstidens intensitet steg voldsomt og urbaniseringens sundhedskonsekvenser var katastrofale. Forventet levealder i Manchester 1840: 28 år mod 40 år på landet. Metodekernes uenighed: optimisterne prioriterer reallønninger som den rigtige velfærdsmålestok. Pessimisterne hævder at velfærd er multidimensional — frihed, sundhed, fællesskab, arbejdsforhold, ikke blot købekraft. Amartya Sens kapabilitetsteori giver den filosofiske understøtning: velfærd er ikke identisk med indkomst men med evnen til at realisere meningsfulde livsformer."}$$::jsonb,
  'mc','short',$${"concepts":["optimister vs pessimister","levestandard","Thompson","McCloskey","reallønninger","velfærdsmålestok"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er E.P. Thompsons vigtigste bidrag til industrialiseringshistoriografien — og hvad er den stærkeste kritik af hans tilgang?","options":["Thompson (The Making of the English Working Class 1963): arbejderklassen var ikke et passivt objekt for historiske kræfter men skabte aktivt sin egen klassebevidsthed og kulturelle identitet — agency og erfaring frem for struktur. Kritik: Thompsons dybe empati med arbejderbevægelsen kan producere en romantisering af håndværkerkulturen og overvurdere kohærensen i en klasse der var langt mere fragmenteret end hans fortælling antyder","Thompson demonstrerede endegyldigt at arbejderklassen ikke eksisterede som en reel historisk aktør — hans bidrag var at afmontere klasse-begrebet","Thompson er fuldstændig korrekt og ingen indvendinger mod hans metode er metodologisk seriøse","Thompsons bidrag er rent anekdotisk og har ingen plads i seriøs kvantitativ industrialiseringshistorie"],"correct":"Thompson (The Making of the English Working Class 1963): arbejderklassen var ikke et passivt objekt for historiske kræfter men skabte aktivt sin egen klassebevidsthed og kulturelle identitet — agency og erfaring frem for struktur. Kritik: Thompsons dybe empati med arbejderbevægelsen kan producere en romantisering af håndværkerkulturen og overvurdere kohærensen i en klasse der var langt mere fragmenteret end hans fortælling antyder","accepted_answers":["Thompson (The Making of the English Working Class 1963): arbejderklassen var ikke et passivt objekt for historiske kræfter men skabte aktivt sin egen klassebevidsthed og kulturelle identitet — agency og erfaring frem for struktur. Kritik: Thompsons dybe empati med arbejderbevægelsen kan producere en romantisering af håndværkerkulturen og overvurdere kohærensen i en klasse der var langt mere fragmenteret end hans fortælling antyder"],"review_text":"E.P. Thompsons The Making of the English Working Class (1963) er et af 1900-tallets mest indflydelsesrige historievidenskabelige værker. Den metodologiske revolution: Thompson afviste den deterministiske Marx-læsning der så klassen som en strukturel position og erstattede den med klasse som kulturel og politisk formation. Luddisterne, Chartisterne og de metodistiske kapeller var alle dele af den fremvoksende klasseidentitet. Thompsons kritikere er metodologisk seriøse: Gareth Stedman Jones (Languages of Class 1983) viste at Chartismens sprog og identitet var mere politisk og diskursivt end Thompson antog. Patrick Joyce hævdede at Thompsons klasse-narrativ underspillede regionale og religiøse identiteter der var ligeså stærke som klassefællesskabet. Agency-struktur-debatten er ikke afsluttet."}$$::jsonb,
  'mc','short',$${"concepts":["Thompson","Making of the English Working Class","agency","klassebevidsthed","romantisering","Stedman Jones"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den revisionistiske historiografis vigtigste udfordring af den klassisk Marx-inspirerede forståelse af industrialiseringen som udbytningssystem?","options":["Revisionisterne (Mokyr, McCloskey) hævder at den industrielle revolution primært var drevet af teknologisk innovation, videnskabelig kultur og entrepreneurs kreativitet — ikke af klassekampdynamik eller kapitalakkumulation via udbytning. McCloskeys 'bourgeois virtues'-tese: det var kulturelle holdningsændringer der legitimerede innovation der muliggjorde industrialiseringen","Revisionistisk historiografi bekræfter grundlæggende Marxs analyse men med moderne terminologi","Revisionism er ren apologetik for kapitalinteresser og producerer ingen ny empirisk indsigt om industrialiseringen","Den klassiske Marxinspirerede analyse er fuldstændig korrekt og revisionism har ikke bidraget med nogen metodologisk eller empirisk indsigt"],"correct":"Revisionisterne (Mokyr, McCloskey) hævder at den industrielle revolution primært var drevet af teknologisk innovation, videnskabelig kultur og entrepreneurs kreativitet — ikke af klassekampdynamik eller kapitalakkumulation via udbytning. McCloskeys 'bourgeois virtues'-tese: det var kulturelle holdningsændringer der legitimerede innovation der muliggjorde industrialiseringen","accepted_answers":["Revisionisterne (Mokyr, McCloskey) hævder at den industrielle revolution primært var drevet af teknologisk innovation, videnskabelig kultur og entrepreneurs kreativitet — ikke af klassekampdynamik eller kapitalakkumulation via udbytning. McCloskeys 'bourgeois virtues'-tese: det var kulturelle holdningsændringer der legitimerede innovation der muliggjorde industrialiseringen"],"review_text":"Joel Mokyrs The Enlightened Economy (2009) og Deirdre McCloskeys Bourgeois Trilogy er de centrale revisionistiske værker. Mokyr argumenterer at den industrielle revolution var dybt forbundet med oplysningstidens videnskabelige kultur og 'the culture of improvement' — en intellektuel åbenhed for teknisk eksperimentering og innovation. McCloskey tilføjer den kulturelle dimension: ændringer i holdningen til handel og borgerskabets virke (fra moralsk mistænkelig til socialt respektabel) skabte den innovationsfremmende kultur. Begge adskiller sig fra marxistisk analyse ved at prioritere ideer og kultur fremfor materielle klassekonflikter. Kritikken af revisionisme: den undervurderer kapitalens rolle og de koloniale ressourcers bidrag til industrialiseringens finansiering. De to fortolkninger er ikke ekskluderende — den stærkeste analyse kombinerer materialisme og idéhistorie."}$$::jsonb,
  'mc','short',$${"concepts":["revisionisme","Mokyr","McCloskey","teknologisk innovation","bourgeois virtues","idéhistorie"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser Kenneth Pomeranz' globalhistoriske perspektiv på 'the Great Divergence' om den eurocentriske forklaring på industrialiseringen?","options":["Pomeranz (The Great Divergence 2000) viser at Englands forspring ikke skyldtes unik europæisk rationalitet eller protestantisk etik alene — men i høj grad tilgang til koloniale ressourcer, kulforekomsters geografi og slaveriejendommens bidrag til kapitalakkumulation. Den eurocentriske forklaring er metodologisk selektiv fordi den ignorerer de globale forbindelser der var forudsætningen for industrialiseringen","Pomeranz bekræfter at europæisk rationalitet og kultur var den afgørende og selvstændige årsag til industrialiseringen","Den eurocentriske forklaring er fuldstændig korrekt og globalhistorisk perspektiv bidrager intet til forståelsen af industrialiseringen","Kina og Europa var identisk positioneret i 1700-tallet og enhver forskel i industrialiseringen skyldtes ren tilfældighed"],"correct":"Pomeranz (The Great Divergence 2000) viser at Englands forspring ikke skyldtes unik europæisk rationalitet eller protestantisk etik alene — men i høj grad tilgang til koloniale ressourcer, kulforekomsters geografi og slaveriejendommens bidrag til kapitalakkumulation. Den eurocentriske forklaring er metodologisk selektiv fordi den ignorerer de globale forbindelser der var forudsætningen for industrialiseringen","accepted_answers":["Pomeranz (The Great Divergence 2000) viser at Englands forspring ikke skyldtes unik europæisk rationalitet eller protestantisk etik alene — men i høj grad tilgang til koloniale ressourcer, kulforekomsters geografi og slaveriejendommens bidrag til kapitalakkumulation. Den eurocentriske forklaring er metodologisk selektiv fordi den ignorerer de globale forbindelser der var forudsætningen for industrialiseringen"],"review_text":"Kenneth Pomeranz The Great Divergence (2000) er et grundlæggende opgør med eurocentrisk industrialiseringshistorie. Pomeranz dokumenterer at Yangtze-deltaet i Kina i 1700-tallets begyndelse var sammenlignelig med England i produktivitet og reallønninger. Divergensen skyldtes kombinationen af: (1) kulforekomsternes geografiske tilfældighed — England havde kul tæt på befolkningscentre, (2) adgang til koloniale ressourcer — Amerika leverede mad og råmaterialer der frigav engelsk arbejdskraft til industrien, og (3) slaveriejendommens kapitalakkumulation der finansierede britisk industri. Eric Williams Capitalism and Slavery (1944) havde allerede argumenteret for slaveriets rolle i den britiske industrialiseringsfinansiering. Globalhistorisk perspektiv er metodologisk afgørende: industrialiseringen var aldrig et isoleret europæisk fænomen."}$$::jsonb,
  'mc','short',$${"concepts":["Pomeranz","Great Divergence","eurocentrisk","kolonialisme","slaveri","globalhistorie"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad kan den industrielle revolutions erfaringer lære os om den digitale revolutions sociale konsekvenser i dag?","options":["Begge revolutioner skabte massiv produktivitetsvækst med skævt fordelte vindere og tabere på kort sigt: håndværkere tabte til fabrikker parallelt med at manuelle arbejdere i dag taber til automatisering. Historien viser at teknologisk transition kræver aktiv politisk håndtering — den ordner ikke sig selv og markedet alene sikrer ikke at gevinster fordeles bredt","Den digitale revolution er fuldstændig anderledes end industrialiseringen og historiske erfaringer er irrelevante for at forstå teknologiske transitions konsekvenser i dag","Teknologisk fremgang gavner altid alle — både industrialiseringen og digitaliseringen forbedrede automatisk alle borgeres vilkår uden politisk intervention","Industrialiseringens erfaringer viser at teknologisk transition altid er udelukkende skadelig og at den digitale revolution bør forhindres for at beskytte eksisterende arbejdspladser"],"correct":"Begge revolutioner skabte massiv produktivitetsvækst med skævt fordelte vindere og tabere på kort sigt: håndværkere tabte til fabrikker parallelt med at manuelle arbejdere i dag taber til automatisering. Historien viser at teknologisk transition kræver aktiv politisk håndtering — den ordner ikke sig selv og markedet alene sikrer ikke at gevinster fordeles bredt","accepted_answers":["Begge revolutioner skabte massiv produktivitetsvækst med skævt fordelte vindere og tabere på kort sigt: håndværkere tabte til fabrikker parallelt med at manuelle arbejdere i dag taber til automatisering. Historien viser at teknologisk transition kræver aktiv politisk håndtering — den ordner ikke sig selv og markedet alene sikrer ikke at gevinster fordeles bredt"],"review_text":"Parallellen er empirisk veldokumenteret og analytisk frugtbar. 1800-tallets håndvævere oplevede lønkollaps på 75% over 1800-1830 da dampdrevne kraftvæve overtog produktionen. Luddisterne der ødelagde maskiner i 1811-16 er historisk fejlfortolket som fremskridtsfjendtlige: de var rationelle aktører der forsøgte at beskytte levevilkår truet af teknologi der gavnede kapitalejerne mens de bar omkostningerne. Daron Acemoglu og Pascual Restrepos forskning (2019) viser at automatisering i dag primært erstatter rutinebaseret arbejde og forværrer ulighed medmindre politisk regulering sikrer omfordeling af produktivitetsvinsterne. MIT-økonomer Brynjolfsson og McAfee (The Second Machine Age) argumenterer at vi er i en analog position til tidlig industrialisering. Industrialiseringens lektion: teknologi er ikke skæbne — politisk valg afgør hvem der bærer byrden og hvem der høster gevinsten."}$$::jsonb,
  'mc','short',$${"concepts":["digital revolution","automatisering","industrialisering","teknologisk transition","Luddisme","Acemoglu"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var den industrielle revolution et globalt fænomen — og hvad var konsekvenserne for ikke-europæiske samfund?","options":["Industrialiseringen var globalt fra starten via sine konsekvenser: billige britiske tekstiler ødelagde indisk håndværksindustri, Latinamerika og Afrika blev råvareleverandører og tvangsarbejde via slaveriet finansierede dele af kapitalakkumulationen. At behandle industrialiseringen som et isoleret europæisk fænomen er et analytisk fejlgreb der skjuler de globale magtrelationer den hvilede på","Den industrielle revolution var et rent europæisk fænomen uden konsekvenser for resten af verden indtil kolonialismens afskaffelse","Industrialiseringen var globalt gavnlig for alle involverede lande fordi frihandel og teknologioverførsel forbedrede velstanden overalt","Konsekvenserne for ikke-europæiske samfund er historisk irrelevante for forståelsen af den industrielle revolution som sådan"],"correct":"Industrialiseringen var globalt fra starten via sine konsekvenser: billige britiske tekstiler ødelagde indisk håndværksindustri, Latinamerika og Afrika blev råvareleverandører og tvangsarbejde via slaveriet finansierede dele af kapitalakkumulationen. At behandle industrialiseringen som et isoleret europæisk fænomen er et analytisk fejlgreb der skjuler de globale magtrelationer den hvilede på","accepted_answers":["Industrialiseringen var globalt fra starten via sine konsekvenser: billige britiske tekstiler ødelagde indisk håndværksindustri, Latinamerika og Afrika blev råvareleverandører og tvangsarbejde via slaveriet finansierede dele af kapitalakkumulationen. At behandle industrialiseringen som et isoleret europæisk fænomen er et analytisk fejlgreb der skjuler de globale magtrelationer den hvilede på"],"review_text":"Indien er det mest dokumenterede eksempel på industrialiseringens globale destruktive konsekvenser: den bengalske tekstilindustri kollapsede under konkurrencen fra maskinfremstillede britiske tekstiler kombineret med importtolden der beskyttede britisk industri mens indiske markeder var tvunget åbne. Mike Daviss Late Victorian Holocausts (2001) dokumenterer at gentagne hungersnøde i Indien, Kina og Latinamerika i 1870-1900-perioden var forbundet med den globale integration i et britisk-domineret handels- og finanssystem. Den transatlantiske slavehandel var strukturelt forbundet med industrialiseringen: bomuldsspinderier i Manchester forarbejdede produktion fra amerikanske slaver. Eric Williams og Walter Rodney How Europe Underdeveloped Africa (1972) analyserer disse forbindelser systematisk. Industrialiseringens globalhistorie er uadskillelig fra kolonialismens og slaveriets globalhistorie."}$$::jsonb,
  'mc','short',$${"concepts":["global industrialisering","Indien","slaveri","kolonialisme","Davis","Rodney"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den vigtigste lektion fra industrialiseringens miljøkonsekvenser for klimakrisen i dag?","options":["At industriel vækst systematisk producerer negative eksternaliteter (forurening, ressourceudtømning) der ikke automatisk prises af markedet — Manchesters floder og Londons smog var eksternaliteter ingen fabriksejer betalte for. CO2-udledning er den samme logik i global skala: en eksternalitet markedet ikke internaliserer uden regulering. Lektionen: aktiv statslig regulering og prissætning af eksternaliteter er nødvendig, ikke frivillig","Industrialiseringens miljøforurening løste sig selv naturligt da velstanden steg — klimakrisen vil løse sig selv på samme måde uden politisk intervention","Industrialiseringen beviser at teknologisk fremgang altid overvinder miljøproblemer og klimakrisen vil løses af grøn teknologi alene uden behov for regulering","Industrialiseringens miljøkonsekvenser er historisk irrelevante for klimaproblematikken fordi de er fundamentalt forskellige fænomener"],"correct":"At industriel vækst systematisk producerer negative eksternaliteter (forurening, ressourceudtømning) der ikke automatisk prises af markedet — Manchesters floder og Londons smog var eksternaliteter ingen fabriksejer betalte for. CO2-udledning er den samme logik i global skala: en eksternalitet markedet ikke internaliserer uden regulering. Lektionen: aktiv statslig regulering og prissætning af eksternaliteter er nødvendig, ikke frivillig","accepted_answers":["At industriel vækst systematisk producerer negative eksternaliteter (forurening, ressourceudtømning) der ikke automatisk prises af markedet — Manchesters floder og Londons smog var eksternaliteter ingen fabriksejer betalte for. CO2-udledning er den samme logik i global skala: en eksternalitet markedet ikke internaliserer uden regulering. Lektionen: aktiv statslig regulering og prissætning af eksternaliteter er nødvendig, ikke frivillig"],"review_text":"Eksternalitetsproblematikken er industrialiseringens centrale miljøøkonomiske lektion. En fabriksejer i Manchester der dumpede kemikalier i floden Irwell betalte ingen pris for skaden på fiskeri og drikkevand nedstrøms — skaden var en eksternalitet der faldt på andre. Arthur Pigou formulerede i The Economics of Welfare (1920) den klassiske løsning: en Pigou-skat der internaliserer eksternaliteten. CO2-udledning er præcis den samme logik i global og temporalt forsinket skala: producenten af fossil energi bærer ikke omkostningen ved klimakonsekvenserne. Kuznets-kurve-hypotesen (miljøforurening stiger med vækst og falder igen ved høj velstand) er empirisk delvist støttet for lokal forurening men ikke for CO2. William Nordhus klimaøkonomi og IPCC-rapporternes anbefalinger om CO2-afgifter er direkte arv fra Pigou-traditionen. Industrialiseringens lektion: markedet internaliserer ikke eksternaliteter spontant — regulering er systemets selvkorrektionsmekanisme."}$$::jsonb,
  'mc','short',$${"concepts":["eksternaliteter","Pigou","forurening","klimakrise","CO2-afgift","markedssvigt"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er globaliseringen i dag en continuation af industrialiseringens logik — eller er der grundlæggende strukturelle brud?","options":["Begge: kapitalakkumulationslogik, international arbejdsdeling og teknologidrevet produktivitetsvækst er kontinuerlig fra industrialiseringen til globaliseringen. Men bruddet er reelt: finanskapitalismens dominans over produktionskapitalisme, produktionsflytning til lavsomkostningslande og digital teknologis adskillelse af produktion og viden udgør kvalitativt nye strukturer","Globaliseringen er en fuldstændig continuation af industrialiseringens logik uden nogen brud — de to er identiske fænomener adskilt blot af tid","Globaliseringen er et fundamentalt nyt fænomen der intet har tilfælles med industrialiseringens principper og erfaringerne fra industrialiseringen er irrelevante","Globaliseringen har opslugt industrialiseringens logik og erstattet den fuldstændig med postindustriel serviceøkonomi uden relevans for historiske paralleller"],"correct":"Begge: kapitalakkumulationslogik, international arbejdsdeling og teknologidrevet produktivitetsvækst er kontinuerlig fra industrialiseringen til globaliseringen. Men bruddet er reelt: finanskapitalismens dominans over produktionskapitalisme, produktionsflytning til lavsomkostningslande og digital teknologis adskillelse af produktion og viden udgør kvalitativt nye strukturer","accepted_answers":["Begge: kapitalakkumulationslogik, international arbejdsdeling og teknologidrevet produktivitetsvækst er kontinuerlig fra industrialiseringen til globaliseringen. Men bruddet er reelt: finanskapitalismens dominans over produktionskapitalisme, produktionsflytning til lavsomkostningslande og digital teknologis adskillelse af produktion og viden udgør kvalitativt nye strukturer"],"review_text":"Kontinuitetsperspektivet: den kapitalistiske akkumulationslogik driver industrialiseringen i Manchester 1840 og offshoring til Bangladesh 2010 med identisk strukturel logik — arbejdskraftens pris arbitrageres globalt. Adam Smiths arbejdsdeling opererer nu i globale forsyningskæder i stedet for i nationale fabrikker. Bruddet er kvalitativt reelt: finanskapitalens dominans (Wallerstein, Arrighi) indebærer at kapital akkumuleres primært via finansielle instrumenter snarere end industriel produktion. Hypermobilitet af kapital (offshoring) svækker nationstaternes reguleringsevne på en måde der er strukturelt anderledes end 1800-tallets relativt immobile kapital. Informationsøkonomi producerer ikke-rivaliserende goder (software, data) der ikke passer i klassisk industrikapitalismens commodities-model. Kontinuitet og brud er ikke modsætninger — de analytiske begreber der er nyttige er dem der præcist identificerer hvad der er hvad."}$$::jsonb,
  'mc','short',$${"concepts":["globalisering","kapitalakkumulation","finanskapitalisme","offshoring","kontinuitet og brud","Arrighi"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"industrialisation"}$$::jsonb,
  'mc_single',5,'auto',true,'industrialisation',9,5
);;
